-- Setup Snowflake objects for dbt using key-pair authentication.
USE ROLE ACCOUNTADMIN;

CREATE OR REPLACE WAREHOUSE DBT_WH
  WITH
    WAREHOUSE_SIZE = 'XSMALL'
    AUTO_SUSPEND = 120
    AUTO_RESUME = TRUE
    INITIALLY_SUSPENDED = FALSE;

CREATE OR REPLACE DATABASE DBT_DEV_DB;

CREATE OR REPLACE ROLE DBT_ROLE;

CREATE OR REPLACE SCHEMA DBT_DEV_DB.JM;

CREATE OR REPLACE USER DBT_USER
  TYPE = SERVICE
  DEFAULT_WAREHOUSE = DBT_WH
  DEFAULT_ROLE = DBT_ROLE
  RSA_PUBLIC_KEY = '';

GRANT ROLE DBT_ROLE TO ROLE SYSADMIN;
GRANT ROLE DBT_ROLE TO USER DBT_USER;

GRANT USAGE ON WAREHOUSE DBT_WH TO ROLE DBT_ROLE;
GRANT MONITOR ON WAREHOUSE DBT_WH TO ROLE DBT_ROLE;

GRANT USAGE ON DATABASE DBT_DEV_DB TO ROLE DBT_ROLE;
GRANT CREATE SCHEMA ON DATABASE DBT_DEV_DB TO ROLE DBT_ROLE;

GRANT USAGE ON SCHEMA DBT_DEV_DB.JM TO ROLE DBT_ROLE;
GRANT ALL PRIVILEGES ON SCHEMA DBT_DEV_DB.JM TO ROLE DBT_ROLE;

GRANT USAGE ON ALL SCHEMAS IN DATABASE DBT_DEV_DB TO ROLE DBT_ROLE;
GRANT USAGE ON FUTURE SCHEMAS IN DATABASE DBT_DEV_DB TO ROLE DBT_ROLE;

GRANT SELECT ON ALL TABLES IN DATABASE DBT_DEV_DB TO ROLE DBT_ROLE;
GRANT SELECT ON FUTURE TABLES IN DATABASE DBT_DEV_DB TO ROLE DBT_ROLE;
GRANT SELECT ON ALL VIEWS IN DATABASE DBT_DEV_DB TO ROLE DBT_ROLE;
GRANT SELECT ON FUTURE VIEWS IN DATABASE DBT_DEV_DB TO ROLE DBT_ROLE;

GRANT IMPORTED PRIVILEGES ON DATABASE SNOWFLAKE TO ROLE DBT_ROLE;

SHOW GRANTS TO USER DBT_USER;
SHOW GRANTS TO ROLE DBT_ROLE;
DESC USER DBT_USER;
